import {loadMaster,renderScene,verifyBoatProtection} from './v10-art/rendererV10.js';import {setValue,selectObject,resetAll,resetCurrent,toggleCompare} from './state.js';import {act2Workbench,updateWorkbench} from './Act2Workbench.js';
export async function mountWorkbench(root,getState,setState,onBack,onLesson){root._act2Abort?.abort();const abort=new AbortController();root._act2Abort=abort;root.innerHTML=act2Workbench(getState());const control=root.querySelector('.act2-control');if(control){/* 调节面板可拖动：按住面板空白处移动，限制在工作台内，不遮挡画布关键处。 */const dragStart=e=>{if(e.button!==0||e.target.closest('button,input,select,textarea,a'))return;const box=control.getBoundingClientRect(),stage=root.getBoundingClientRect(),startX=e.clientX,startY=e.clientY,left=box.left-stage.left,top=box.top-stage.top;control.style.right='auto';control.style.left=left+'px';control.style.top=top+'px';control.classList.add('is-dragging');const move=ev=>{const maxX=Math.max(0,stage.width-box.width),maxY=Math.max(0,stage.height-box.height);control.style.left=Math.min(maxX,Math.max(0,left+ev.clientX-startX))+'px';control.style.top=Math.min(maxY,Math.max(0,top+ev.clientY-startY))+'px'};const end=()=>{control.classList.remove('is-dragging');window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);window.removeEventListener('pointercancel',end)};window.addEventListener('pointermove',move,{signal:abort.signal});window.addEventListener('pointerup',end,{signal:abort.signal});window.addEventListener('pointercancel',end,{signal:abort.signal});e.preventDefault()};control.addEventListener('pointerdown',dragStart,{signal:abort.signal})}const canvas=root.querySelector('.act2-canvas'),status=root.querySelector('.act2-status'),slider=root.querySelector('[data-act2-slider]');let master,frame=0;const paint=()=>{if(!master)return;frame=0;renderScene(canvas,getState(),master)};const schedulePaint=()=>{if(!frame)frame=requestAnimationFrame(paint)};const commit=next=>{setState(next);updateWorkbench(root,next);schedulePaint()};root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.act2Select){commit(selectObject(getState(),b.dataset.act2Select));slider.focus();return}const a=b.dataset.act2Action;if(a==='back')onBack();else if(a==='lesson')onLesson?.();else if(a==='compare')commit(toggleCompare(getState()));else if(a==='reset-current')commit(resetCurrent(getState()));else if(a==='reset-all')commit(resetAll(getState()))},{signal:abort.signal});root.addEventListener('input',e=>{if(e.target.matches('[data-act2-slider]'))commit(setValue(getState(),getState().selected,e.target.value))},{signal:abort.signal});try{master=await loadMaster()}catch(error){status.textContent=error.message;return{destroy(){abort.abort()}}}if(abort.signal.aborted)return{destroy(){}};paint();const isolation=verifyBoatProtection(master);status.textContent=isolation.tested?(isolation.pass?'船篷静态像素保护：通过':'船篷静态像素保护：失败'):'船篷静态像素保护：待浏览器验证';return{destroy(){if(frame)cancelAnimationFrame(frame);abort.abort()}}}


